  d.diaryPhotoGap=Math.round(characterImageValue(value.diaryPhotoGap,0,160,48));d.diaryPhotoSideGap=Math.round(characterImageValue(value.diaryPhotoSideGap,0,80,12));if(!value.imageLayoutRevision&&value.diaryPhotoSideGap===6)d.diaryPhotoSideGap=12;d.imageLayoutRevision=1;d.diaryPhotoColorRole=['bg','ink','accent','thought','line','custom'].includes(value.diaryPhotoColorRole)?value.diaryPhotoColorRole:value.diaryPhotoCustomColor?'custom':DEFAULTS.diaryPhotoColorRole;d.diaryPhotoCustomColor=d.diaryPhotoColorRole==='custom';d.diaryPhotoColor=FogLogic.colorHex(d.diaryPhotoColor,DEFAULTS.diaryPhotoColor);d.characterFont=Object.hasOwn(BODY_FONTS,d.characterFont)?d.characterFont:'auto';
  d.version=3;d.sections=Array.isArray(value.sections)?value.sections.filter(s=>s&&typeof s==='object'&&typeof s.body==='string').map(s=>({title:typeof s.title==='string'?s.title:'',body:s.body,fold:!!s.fold,open:false})):[];d.paper=[...Object.keys(FogLogic.THEMES),'transparent','custom'].includes(d.paper)?d.paper:'ivory';d.transparentInk=d.transparentInk==='light'?'light':'dark';d.videoStyle=d.videoStyle==='link'?'link':'player';d.dividerStyle=Object.hasOwn(DIVIDERS,d.dividerStyle)?d.dividerStyle:'single';
