function editorWidthBounds(){return {min:200,max:Math.max(200,Math.floor(workspace.clientWidth-320))};}
function applyEditorWidth(value=preferredEditorWidth,remember=false){
  const {min,max}=editorWidthBounds(),fallback=parseFloat(getComputedStyle(workspace).getPropertyValue('--editor-default-width'))||292;
  const width=Math.round(Math.max(min,Math.min(max,Number.isFinite(value)?value:fallback)));
  workspace.style.setProperty('--editor-width',width+'px');
  editorResizer.setAttribute('aria-valuenow',String(width));editorResizer.setAttribute('aria-valuemax',String(max));editorResizer.setAttribute('aria-valuetext',width+'px');
  if(remember){preferredEditorWidth=width;try{localStorage.setItem(EDITOR_WIDTH_KEY,String(width));}catch{}}
  return width;
}
function endEditorResize(cancel=false){
  if(!editorResize)return;const state=editorResize;editorResize=null;document.body.classList.remove('resizing-editor');
  applyEditorWidth(cancel?state.width:parseFloat(workspace.style.getPropertyValue('--editor-width')),!cancel);
  if(editorResizer.hasPointerCapture(state.id))editorResizer.releasePointerCapture(state.id);
}
editorResizer.addEventListener('pointerdown',event=>{
  if(event.button!==0||innerWidth<=600)return;event.preventDefault();finishPreviewEdit();
  editorResize={id:event.pointerId,x:event.clientX,width:$('editor').getBoundingClientRect().width};
  editorResizer.setPointerCapture(event.pointerId);editorResizer.focus({preventScroll:true});document.body.classList.add('resizing-editor');
});
editorResizer.addEventListener('pointermove',event=>{if(editorResize?.id===event.pointerId)applyEditorWidth(editorResize.width+event.clientX-editorResize.x);});
