editorResizer.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&editorResize){event.preventDefault();endEditorResize(true);return;}
  if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();
  const {min,max}=editorWidthBounds(),width=$('editor').getBoundingClientRect().width,step=event.shiftKey?50:10;
  applyEditorWidth(event.key==='Home'?min:event.key==='End'?max:width+(event.key==='ArrowRight'?step:-step),true);
});
