function createSelectionFormatTools(apply){
  const tools=document.createElement('div');tools.className='selection-format-tools';tools.setAttribute('role','group');tools.setAttribute('aria-label','선택한 글 서식');
  for(const [format,label]of [['italic','기울임'],['bold','볼드'],['both','기울임+볼드'],['double','큰따옴표'],['single','작은따옴표']]){
    const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.selectionFormat=format;button.disabled=true;button.addEventListener('click',()=>apply(format));tools.appendChild(button);
  }
  return tools;
}
function mountSelectionFormatTools(textarea,update){
  const tools=createSelectionFormatTools(format=>{
    const start=textarea.selectionStart,end=textarea.selectionEnd,selected=textarea.value.slice(start,end);if(!selected.trim())return;
    const text=FogLogic.formatSelectedText(selected,format);textarea.focus();textarea.setSelectionRange(start,end);
    if(!document.execCommand('insertText',false,text))textarea.setRangeText(text,start,end,'select');
    textarea.setSelectionRange(start,start+text.length);update(textarea.value);render();saveDraft();refresh();toast('선택한 글에 서식을 적용했어요.');
  });
  tools.dataset.formatTarget=textarea.id;textarea.before(tools);
  const refresh=()=>{const selected=textarea.value.slice(textarea.selectionStart,textarea.selectionEnd);tools.querySelectorAll('button').forEach(button=>button.disabled=!selected.trim());};
  for(const name of ['select','input','keyup','pointerup','focus'])textarea.addEventListener(name,refresh);
}
