  if(['imageX','imageY','imageZoom'].includes(key))value=characterImageValue(value,key==='imageZoom'?100:0,key==='imageZoom'?300:100,key==='imageZoom'?100:50);
  if(key==='image'){
    const raw=value.trim(),hint=panel.querySelector('[data-image-hint]');value=safeURL(raw);
    if(raw&&!value){input.setAttribute('aria-invalid','true');hint.textContent='// 또는 https://로 시작하는 이미지 주소를 넣어 주세요.';hint.hidden=false;return;}
    input.removeAttribute('aria-invalid');hint.textContent='';hint.hidden=true;if(canonicalize||raw.startsWith('//'))input.value=value;
  }
